import{c as a,Q as d,j as i,m as s}from"./chunks/framework.DOi4mjdC.js";const h=JSON.parse('{"title":"概述","description":"","frontmatter":{},"headers":[{"level":1,"title":"概述","slug":"概述"}],"relativePath":"api/SIMT-API/概述.md","filePath":"api/SIMT-API/概述.md"}'),o={name:"api/SIMT-API/概述.md"};function e(_,t,n,u,p,l){return d(),i("div",null,[...t[0]||(t[0]=[s(`<h1 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h1><p>SIMT API是面向AI处理器的并行计算编程接口，可以实现高效的数据并行计算。SIMT API支持两种编程模型：SIMT编程、SIMD与SIMT混合编程，用户可先阅读<a href="./SIMT编程简介/SIMT编程简介.html">SIMT编程简介</a>和<a href="./SIMD与SIMT混合编程简介/SIMD与SIMT混合编程简介.html">SIMD与SIMT混合编程简介</a>，以了解编程基础，后续章节将详细介绍API接口。</p><p><strong>表 1</strong> SIMT API分类列表</p><table tabindex="0"><thead><tr><th>类别</th><th>功能</th></tr></thead><tbody><tr><td>同步与内存栅栏</td><td>内存管理与同步接口，解决不同核内的线程间可能存在的数据竞争以及线程的同步问题。</td></tr><tr><td>原子操作</td><td>对Unified Buffer或Global Memory上的数据与指定数据执行原子操作的一系列接口。</td></tr><tr><td>Warp函数</td><td>对单个Warp内32个线程的数据进行处理的相关操作的一系列API接口。</td></tr><tr><td>数学函数</td><td>用于处理数学运算的函数集合以及不同精度、数据类型的转换函数集合</td></tr><tr><td>地址空间谓词函数</td><td>判断输入指针是否为指定空间的地址。</td></tr><tr><td>地址空间转换函数</td><td>将指定地址空间的地址值转换为指针，或将输入的指针转换为对应内存空间的地址值的接口。</td></tr><tr><td>访存函数</td><td>数据加载和数据缓存相关接口。</td></tr><tr><td>调测接口</td><td>SIMT VF调试场景下使用的相关接口。</td></tr></tbody></table><p>Ascend C SIMT API支持通过包含simt_api/asc_simt.h文件来调用输入数据为除half、half2、bfloat16_t、bfloat16x2_t、hifloat8x2_t、float8_e4m3x2_t、float8_e5m2x2_t以外类型的接口，调用输入数据为half和half2类型的SIMT API需要包含simt_api/asc_fp16.h文件，调用输入数据为bfloat16_t和bfloat16x2_t类型的SIMT API需要包含simt_api/asc_bf16.h文件，调用输入数据为hifloat8x2_t、float8_e4m3x2_t和float8_e5m2x2_t类型的SIMT API需要包含simt_api/asc_fp8.h文件。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &quot;simt_api/asc_simt.h&quot;</span></span>
<span class="line"><span>#include &quot;simt_api/asc_fp16.h&quot;</span></span>
<span class="line"><span>#include &quot;simt_api/asc_bf16.h&quot;</span></span>
<span class="line"><span>#include &quot;simt_api/asc_fp8.h&quot;</span></span></code></pre></div><p><strong>表 2</strong> SIMT API需要包含的头文件</p><table tabindex="0"><thead><tr><th>类别</th><th>除half、half2、bfloat16、bfloat16x2_t之外的类型需要包含的头文件</th><th>half、half2类型需要包含的头文件</th><th>bfloat16_t、bfloatx2_t类型需要包含的头文件</th><th>hifloat8x2_t、float8_e4m3x2_t、float8_e5m2x2_t类型需要包含的头文件</th></tr></thead><tbody><tr><td>同步与内存栅栏</td><td>#include &quot;simt_api/device_sync_functions.h&quot;</td><td>#include &quot;simt_api/asc_fp16.h&quot;</td><td>#include &quot;simt_api/asc_bf16.h&quot;</td><td>#include &quot;simt_api/asc_fp8.h&quot;</td></tr><tr><td>原子操作</td><td>#include &quot;simt_api/device_atomic_functions.h&quot;</td><td>#include &quot;simt_api/asc_fp16.h&quot;</td><td>#include &quot;simt_api/asc_bf16.h&quot;</td><td>#include &quot;simt_api/asc_fp8.h&quot;</td></tr><tr><td>Warp函数</td><td>#include &quot;simt_api/device_warp_functions.h&quot;</td><td>#include &quot;simt_api/asc_fp16.h&quot;</td><td>#include &quot;simt_api/asc_bf16.h&quot;</td><td>#include &quot;simt_api/asc_fp8.h&quot;</td></tr><tr><td>数学函数</td><td>#include &quot;simt_api/math_functions.h&quot; #include &quot;simt_api/device_functions.h&quot;</td><td>#include &quot;simt_api/asc_fp16.h&quot;</td><td>#include &quot;simt_api/asc_bf16.h&quot;</td><td>#include &quot;simt_api/asc_fp8.h&quot;</td></tr><tr><td>地址空间谓词函数 地址空间转换函数 访存函数</td><td>#include &quot;simt_api/device_function.h&quot;</td><td>#include &quot;simt_api/asc_fp16.h&quot;</td><td>#include &quot;simt_api/asc_bf16.h&quot;</td><td>#include &quot;simt_api/asc_fp8.h&quot;</td></tr></tbody></table>`,8)])])}const r=a(o,[["render",e]]);export{h as __pageData,r as default};
